(_SI_GUID_5, 'active', 'live', '_SI_NOWTIME_', NULL, _SI_GUID_1, 'Header', 0, '{"tag":"div","style":{"position":"relative","width":"100%","height":"auto"}}', '(function () {
    function init() {
        var path = window.location.pathname.replace(/\/+$/, '') || '/';
        var home = path === '/' || /\/index\.php$/i.test(path) || document.body.hasAttribute('data-si-preview');
        document.body.classList.add(home ? 'si-home' : 'si-subpage');
        var sidebar = document.getElementById('si_default_sidebar');
        var menu = document.getElementById('si_menu_toggle');
        var scrim = document.getElementById('si_sidebar_scrim');
        var account = document.getElementById('si_account_toggle');
        var search = document.getElementById('si_page_search');
        var status = document.getElementById('si_search_status');
        var groups = Array.from(sidebar.querySelectorAll('details'));
        var links = Array.from(sidebar.querySelectorAll('#si_page_nav a'));

        function closeMenu(restoreFocus) {
            document.body.classList.remove('si-menu-open');
            menu.setAttribute('aria-expanded', 'false');
            scrim.hidden = true;
            if (restoreFocus) menu.focus();
        }
        menu.addEventListener('click', function () {
            var open = document.body.classList.toggle('si-menu-open');
            menu.setAttribute('aria-expanded', String(open));
            scrim.hidden = !open;
            if (open) search.focus();
        });
        scrim.addEventListener('click', function () { closeMenu(true); });
        links.forEach(function (link) {
            link.addEventListener('click', function () {
                closeMenu(false);
                links.forEach(function (item) { item.removeAttribute('aria-current'); });
                link.setAttribute('aria-current', 'location');
                var target = document.querySelector(link.getAttribute('href'));
                if (target) {
                    target.setAttribute('tabindex', '-1');
                    target.focus({preventScroll: true});
                }
            });
        });
        document.getElementById('si_expand_nav').addEventListener('click', function () {
            groups.forEach(function (group) { group.open = true; });
        });
        document.getElementById('si_collapse_nav').addEventListener('click', function () {
            groups.forEach(function (group) { group.open = false; });
        });
        var expandedBeforeSearch;
        search.addEventListener('input', function () {
            var query = search.value.trim().toLowerCase();
            if (query && !expandedBeforeSearch) expandedBeforeSearch = groups.map(function (group) { return group.open; });
            var matches = 0;
            links.forEach(function (link) {
                var section = document.querySelector(link.getAttribute('href'));
                var text = link.textContent + ' ' + (section ? section.textContent : '');
                var match = !query || text.toLowerCase().includes(query);
                link.parentElement.hidden = !match;
                if (match) matches++;
            });
            groups.forEach(function (group, index) {
                group.hidden = !Array.from(group.querySelectorAll('li')).some(function (item) { return !item.hidden; });
                if (query && !group.hidden) group.open = true;
                else if (!query && expandedBeforeSearch) group.open = expandedBeforeSearch[index];
            });
            if (!query) expandedBeforeSearch = null;
            status.textContent = query ? (matches ? matches + ' matching section' + (matches === 1 ? '' : 's') + '.' : 'No matching sections. Try “blocks” or “publish”.') : 'Pages, tools, and a place to start.';
        });
        if (!document.getElementById('si_block_Login')) {
            account.hidden = true;
        } else {
            var name = window.SI && SI.User && SI.User.Name;
            if (name && name !== 'guest') account.textContent = 'Account';
            account.addEventListener('click', function () {
                var open = document.body.classList.toggle('si-account-open');
                account.setAttribute('aria-expanded', String(open));
                if (open) {
                    var field = document.querySelector('#si_block_Login input[type="email"]');
                    if (field && field.offsetParent !== null) field.focus();
                }
            });
        }
        document.addEventListener('keydown', function (event) {
            if (event.key === 'Escape') {
                if (document.body.classList.contains('si-menu-open')) closeMenu(true);
                if (document.body.classList.contains('si-account-open')) {
                    document.body.classList.remove('si-account-open');
                    account.setAttribute('aria-expanded', 'false');
                    account.focus();
                }
            }
            if (home && event.key === '/' && !event.ctrlKey && !event.metaKey && !event.altKey && !event.target.closest('input, textarea, select, [contenteditable]')) {
                event.preventDefault();
                if (window.matchMedia('(max-width: 760px)').matches && !document.body.classList.contains('si-menu-open')) menu.click();
                search.focus();
            }
        });
        if (home && 'IntersectionObserver' in window) {
            var observer = new IntersectionObserver(function (entries) {
                var visible = entries.filter(function (entry) { return entry.isIntersecting; });
                if (!visible.length || search.value.trim()) return;
                var active = visible.sort(function (a, b) { return a.boundingClientRect.top - b.boundingClientRect.top; })[0].target.id;
                links.forEach(function (link) {
                    if (link.hash === '#' + active) link.setAttribute('aria-current', 'location');
                    else link.removeAttribute('aria-current');
                });
            }, {rootMargin: '-100px 0px -60% 0px', threshold: 0});
            document.querySelectorAll('#si_default_main > section[id]').forEach(function (section) { observer.observe(section); });
        }
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once: true});
    else init();
})();', ':root {
  color-scheme: dark;
  --si-bg: #0b1120;
  --si-surface: #121d30;
  --si-line: #2b3d56;
  --si-text: #e8edf7;
  --si-muted: #a8b7cf;
  --si-accent: #7fb5ff;
  --si-code: #0c1729;
  scroll-padding-top: 90px;
}
body {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: radial-gradient(ellipse at 50% -20%, #24446b 0%, transparent 55%), linear-gradient(145deg, #0c1425, #090e19) !important;
  background-color: var(--si-bg) !important;
  color: var(--si-text) !important;
  font: 15px/1.75 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  min-height: 100vh;
}
#si_colorscheme { display: none; }
.si-topbar, .si-sidebar, .si-content, .si-doc-footer,
.si-topbar *, .si-sidebar *, .si-content *, .si-doc-footer * { box-sizing: border-box; }
.si-topbar a, .si-sidebar a, .si-content a, .si-doc-footer a { color: var(--si-accent); text-underline-offset: 3px; }
.si-topbar button, .si-sidebar button, .si-sidebar input { font: inherit; }
.si-topbar button, .si-sidebar button { cursor: pointer; }
:is(.si-topbar, .si-sidebar, .si-content, .si-doc-footer) :is(a, button, input, summary, [tabindex]):focus-visible { outline: 2px solid var(--si-accent); outline-offset: 4px; }
::selection { color: #101827; background: var(--si-accent); }
[hidden] { display: none !important; }
#si_block_Header { display: contents !important; }
#si_block_Menu, #si_block_Footer { position: relative !important; top: auto !important; left: auto !important; width: 100% !important; height: auto !important; background: transparent !important; }
.si-skip { position: fixed; top: -80px; left: 12px; z-index: 100; padding: 10px 14px; color: #101827; background: var(--si-accent); }
.si-skip:focus { top: 12px; }
.si-topbar { position: sticky; top: 0; z-index: 20; height: 72px; display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 0 28px; border-bottom: 1px solid var(--si-line); background: #0b1120f5; backdrop-filter: blur(12px); }
.si-topbar .si-brand { color: var(--si-text); text-decoration: none; font: 700 21px/1.15 Consolas, "Liberation Mono", monospace; letter-spacing: -1px; white-space: nowrap; }
.si-brand span { font-weight: 400; }
.si-brand b { color: var(--si-accent); }
.si-brand small { display: block; margin-top: 5px; font: 400 10px/1.3 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; letter-spacing: .025em; color: var(--si-muted); }
.si-top-nav { display: flex; align-items: center; gap: 23px; color: var(--si-muted); font-size: 12px; }
.si-top-nav > a { color: var(--si-muted); text-decoration: none; }
.si-top-nav > a:hover, .si-doc-footer a:hover { color: var(--si-accent); }
.si-version { padding: 4px 9px; border: 1px solid var(--si-line); border-radius: 3px; font: 10px Consolas, monospace; letter-spacing: .04em; white-space: nowrap; }
.si-small-button { color: var(--si-text); border: 1px solid #36516f; border-radius: 3px; background: var(--si-surface); padding: 5px 11px; white-space: nowrap; }
.si-small-button:hover { background: #21324a; }
.si-menu-toggle { display: none; }
.si-sidebar { position: fixed; z-index: 10; top: 72px; bottom: 0; left: max(0px, calc((100vw - 1500px) / 2)); width: 292px; padding: 30px 23px 36px; border-right: 1px solid var(--si-line); overflow-y: auto; scrollbar-width: thin; scrollbar-color: #36516f transparent; }
.si-search-label { display: block; margin-bottom: 9px; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--si-muted); }
.si-search-row { position: relative; }
.si-search-row input { width: 100%; padding: 9px 34px 9px 11px; border: 1px solid #36516f; border-radius: 4px; background: var(--si-surface); color: var(--si-text); font-size: 12px; }
.si-search-row input::placeholder { color: #91a4bf; }
.si-search-row kbd { position: absolute; right: 12px; top: 10px; font: 12px Consolas, monospace; color: var(--si-muted); pointer-events: none; }
.si-search-status { min-height: 20px; margin: 8px 0; font-size: 10px; color: var(--si-muted); }
.si-tree-controls { display: flex; gap: 16px; margin: 13px 0 20px; }
.si-tree-controls button { padding: 0; border: 0; background: none; color: var(--si-muted); font-size: 10px; }
.si-tree-controls button:hover { color: var(--si-accent); }
.si-toc-group { margin-bottom: 9px; }
.si-toc-group > summary { padding: 7px 3px; font-size: 12px; font-weight: 600; color: #eaf1fc; cursor: pointer; list-style-position: inside; }
.si-toc-group > summary::marker { color: #8da2bd; font-size: 10px; }
.si-toc-group ul { margin: 0; padding: 1px 0 8px 15px; list-style: none; }
.si-toc-group li { margin: 0; }
.si-toc-group a { display: block; padding: 7px 12px; border-left: 1px solid #293c55; color: var(--si-muted); font-size: 12px; line-height: 1.45; text-decoration: none; }
.si-toc-group a:hover { background: #21324a; color: var(--si-text); }
.si-toc-group a[aria-current="location"] { padding-left: 11px; border-left: 2px solid var(--si-accent); background: #24446b; color: var(--si-accent); }
.si-sidebar-note { margin-top: 26px; padding-top: 18px; border-top: 1px solid var(--si-line); color: #8193ae; font-size: 11px; line-height: 1.85; }
.si-sidebar-note a { display: inline-block; margin-top: 10px; text-decoration: none; }
.si-sidebar-scrim { position: fixed; inset: 72px 0 0; z-index: 8; border: 0; background: #0008; }
#si_block_Menu, #si_block_Footer { max-width: 1500px; margin: 0 auto; }
.si-content { min-width: 0; max-width: 1208px; margin-left: 292px; padding: 50px clamp(28px, 4.2vw, 70px) 70px; }
.si-intro { padding-bottom: 36px; margin-bottom: 45px; border-bottom: 1px solid var(--si-line); }
.si-content .si-eyebrow { margin: 0 0 17px; color: var(--si-accent); font: 10px/1.6 Consolas, "Liberation Mono", monospace; letter-spacing: .13em; text-transform: uppercase; }
.si-content h1 { margin: 0 0 23px; font-size: clamp(38px, 4.05vw, 58px); font-weight: 550; line-height: 1.14; letter-spacing: -.052em; }
.si-intro > p:not(.si-eyebrow) { max-width: 65ch; margin: 0; color: #b3c2d8; font-size: 16px; line-height: 1.85; }
.si-intro-tags { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 23px; }
.si-intro-tags span { padding: 4px 9px; border: 1px solid #293c55; border-radius: 3px; background: var(--si-code); color: #c7d9f8; font: 10px/1.6 Consolas, monospace; }
.si-quick-start { display: flex; flex-wrap: wrap; gap: 24px; margin-top: 24px; font-size: 12px; }
.si-quick-start a { text-decoration: none; }
.si-quick-start a:hover { text-decoration: underline; }
.si-quick-start a span { margin-left: 6px; }
.si-chapter { margin: 0 0 58px; scroll-margin-top: 94px; }
.si-chapter + .si-chapter { padding-top: 27px; border-top: 1px solid var(--si-line); }
.si-chapter .si-eyebrow { margin-bottom: 11px; }
.si-content h2 { margin: 0 0 15px; font-size: 29px; font-weight: 550; line-height: 1.3; letter-spacing: -.035em; }
.si-content h3 { margin: 0 0 5px; color: #eaf1fc; font-size: 15px; font-weight: 600; line-height: 1.5; letter-spacing: -.01em; }
.si-chapter > p:not(.si-eyebrow) { margin: 0 0 22px; max-width: 85ch; color: #b3c2d8; font-size: 14px; line-height: 1.85; }
.si-start-steps { list-style: none; margin: 25px 0; padding: 0; }
.si-start-steps li { display: flex; align-items: flex-start; gap: 18px; margin: 17px 0; }
.si-step-index { flex: 0 0 31px; padding-top: 4px; font: 12px/1.7 Consolas, monospace; color: var(--si-accent); }
.si-start-steps p { margin: 0; color: var(--si-muted); font-size: 13px; }
.si-note { padding: 13px 17px; border-left: 2px solid var(--si-accent); background: var(--si-surface); color: #b3c2d8; font-size: 12px; }
.si-note strong { font-weight: 600; color: var(--si-text); }
.si-workspace { margin: 25px 0 0; border: 1px solid var(--si-line); border-radius: 5px; background: var(--si-code); overflow: hidden; }
.si-workspace figcaption { display: flex; justify-content: space-between; gap: 12px; padding: 11px 16px; border-bottom: 1px solid var(--si-line); background: var(--si-surface); color: var(--si-muted); font: 10px/1.6 Consolas, monospace; letter-spacing: .04em; }
.si-status-dot { display: inline-block; height: 6px; width: 6px; margin-right: 7px; border-radius: 50%; background: #a4efbc; }
.si-workspace-body { display: grid; grid-template-columns: 185px minmax(0, 1fr); min-height: 270px; }
.si-demo-label { display: block; margin-bottom: 18px; color: #8da2bd; font: 9px/1.6 Consolas, monospace; letter-spacing: .09em; }
.si-outline { padding: 22px 16px; border-right: 1px solid var(--si-line); font-size: 12px; color: #c7d9f8; }
.si-outline > div > span { margin-right: 7px; color: #8da2bd; }
.si-outline ul { margin: 8px 0 28px; padding: 0 0 0 12px; list-style: none; }
.si-outline li { padding: 6px 9px; border-left: 1px solid #293c55; font-size: 11px; color: var(--si-muted); }
.si-outline li.si-outline-selected { border-left-color: var(--si-accent); background: #24446b; color: var(--si-accent); }
